// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address ownerProxy, address newOwner) public {
        vm.assume(ownerProxy != address(0));

        Forwarder f = new Forwarder(c);

        bool ok;
        try c.setOwner(address(f)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);

        bool ok2;
        try f.callSetOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok2);
    }
}

contract Forwarder {
    Owned immutable target;
    constructor(Owned _target) {
        target = _target;
    }
    function callSetOwner(address _owner) external {
        target.setOwner(_owner);
    }
}
